import{STATUSES,validateData,localDate,isOverdue,selectTickets,nextId}from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='project-desk-v1',now=()=>new Date().toISOString();
function seed(){const date=localDate(),at=now();return{version:1,projects:[{id:'getting-started',name:'Getting started',color:'#6c9276'},{id:'personal',name:'Personal projects',color:'#a195c0'},{id:'home',name:'Home & life',color:'#c7a66d'}],tickets:[{id:1,title:'Make this workspace your own',project:'getting-started',status:'In progress',priority:'High',due:date,description:'Welcome to Project Desk. These are example tickets you can edit or delete. Create a project with the + beside Projects, then add your own tickets.\n\nMy focus shows active work, high-priority tickets, and tickets due today or earlier. Your data stays in this browser. Use Backup to keep a copy.',checks:[{text:'Create your first project',done:false},{text:'Add a ticket for your next step',done:false},{text:'Download a backup',done:false}],history:[{at,text:'Example ticket created.'}],created:at,updated:at},{id:2,title:'Capture an idea for your next project',project:'personal',status:'New',priority:'Normal',due:'',description:'Give your idea a title, then capture the next small step in a checklist.',checks:[],history:[{at,text:'Example ticket created.'}],created:at,updated:at},{id:3,title:'Plan one small improvement at home',project:'home',status:'Waiting',priority:'Low',due:'',description:'Use Waiting for things that depend on a delivery, a decision, or someone else.',checks:[],history:[{at,text:'Example ticket created.'}],created:at,updated:at},{id:4,title:'Set up a place to track projects',project:'getting-started',status:'Resolved',priority:'Normal',due:'',description:'A small win to get you started.',checks:[],history:[{at,text:'Example ticket resolved.'}],created:at,updated:at}]};}
let data,storageIssue=false;try{const raw=localStorage.getItem(KEY);data=raw?validateData(JSON.parse(raw)):seed();}catch{storageIssue=true;data={version:1,projects:[{id:'personal',name:'Personal projects',color:'#6c9276'}],tickets:[]};}
let state={scope:'all',project:'',view:'list',search:'',status:'',priority:''},editing=null,checks=[];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(next){try{validateData(next);localStorage.setItem(KEY,JSON.stringify(next));data=next;storageIssue=false;$('#save-state').textContent='Saved on this browser';return true;}catch(e){toast('Could not save. Your existing data was kept. '+e.message);return false;}}
const projectOf=t=>data.projects.find(p=>p.id===t.project),dateLabel=s=>s?new Date(s+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}):'No due date',badge=s=>`<span class="badge ${s.replaceAll(' ','-')}">● ${esc(s)}</span>`,priority=p=>`<span class="priority ${p}">${({Urgent:'⚑',High:'↑',Normal:'−',Low:'↓'})[p]} ${p}</span>`;
function projectTag(t){const p=projectOf(t);return `<span class="project-tag" style="--project-color:${p.color}"><i></i>${esc(p.name)}</span>`;}
function render(){
 const p=data.projects.find(p=>p.id===state.project),title=p?p.name:({all:'All tickets',focus:'My focus',done:'Resolved'})[state.scope];$('#crumb').textContent=title;$('#page-title').textContent=title;$('#page-subtitle').textContent=state.scope==='focus'?'Active work, important tickets, and things coming due.':state.scope==='done'?'A little record of the progress you’ve made.':'A clear place for everything you’re working on.';
 $('#all-count').textContent=data.tickets.filter(t=>t.status!=='Resolved').length;
 document.querySelectorAll('[data-scope]').forEach(b=>b.classList.toggle('active',!state.project&&b.dataset.scope===state.scope));
 $('#projects').innerHTML=data.projects.map(p=>`<button class="project-nav ${p.id===state.project?'active':''}" data-project="${esc(p.id)}"><span class="dot" style="--project-color:${p.color}"></span>${esc(p.name)}</button>`).join('');
 const base=data.tickets.filter(t=>!state.project||t.project===state.project),stats=[['Open tickets',base.filter(t=>t.status!=='Resolved').length,'Ideas and work in motion','◌'],['In progress',base.filter(t=>t.status==='In progress').length,'One step at a time','◉'],['Overdue',base.filter(t=>isOverdue(t)).length,'Ready for a fresh look','◷'],['Resolved',base.filter(t=>t.status==='Resolved').length,'Every finish counts','✓']];
 $('#stats').innerHTML=stats.map(([label,n,caption,icon])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${n}</div><div class="stat-caption">${caption}</div></div>`).join('');
 const ts=selectTickets(data,state);$('#result-count').textContent=`${ts.length} ticket${ts.length===1?'':'s'}`;
 if(state.view==='board')$('#tickets').innerHTML=`<div class="board">${STATUSES.map(s=>`<section class="column"><div class="column-heading">${s}<b>${ts.filter(t=>t.status===s).length}</b></div>${ts.filter(t=>t.status===s).map(t=>`<button class="card" data-ticket="${t.id}"><span class="ticket-id">#${String(t.id).padStart(3,'0')}</span><span class="ticket-title">${esc(t.title)}</span>${projectTag(t)}<div class="card-bottom">${priority(t.priority)}<span class="due ${isOverdue(t)?'overdue':''}">${dateLabel(t.due)}</span></div></button>`).join('')}</section>`).join('')}</div>`;
 else $('#tickets').innerHTML=ts.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>TICKET</th><th>STATUS</th><th>PRIORITY</th><th>PROJECT</th><th>DUE DATE</th></tr></thead><tbody>${ts.map(t=>`<tr tabindex="0" role="button" aria-label="Open ticket ${t.id}: ${esc(t.title)}" data-ticket="${t.id}"><td class="ticket-id">#${String(t.id).padStart(3,'0')}</td><td><span class="ticket-title">${esc(t.title)}</span><span class="ticket-meta">${t.checks.length?`${t.checks.filter(c=>c.done).length}/${t.checks.length} steps complete`:'Personal ticket'}</span></td><td>${badge(t.status)}</td><td>${priority(t.priority)}</td><td>${projectTag(t)}</td><td class="due ${isOverdue(t)?'overdue':''}">${dateLabel(t.due)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>A little breathing room.</h3>No tickets match this view. Create a ticket or adjust your filters.</div>`;
}
function renderChecks(){$('#checklist').innerHTML=checks.map((c,i)=>`<div class="check-row"><input type="checkbox" data-check="${i}" ${c.done?'checked':''} aria-label="Complete ${esc(c.text)}"><span>${esc(c.text)}</span><button type="button" data-remove-check="${i}" aria-label="Remove step">×</button></div>`).join('');}
function openTicket(id){editing=data.tickets.find(t=>t.id===id)||null;const f=$('#ticket-form');f.reset();f.elements.project.innerHTML=data.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');f.elements.project.value=editing?.project||state.project||data.projects[0].id;for(const key of ['title','status','priority','due','description'])if(editing)f.elements[key].value=editing[key];checks=structuredClone(editing?.checks||[]);renderChecks();$('#check-input').value='';$('#ticket-ref').textContent=editing?`TICKET #${String(editing.id).padStart(3,'0')}`:'NEW TICKET';$('#editor-heading').textContent=editing?'Keep things moving.':'Make room for an idea.';$('#delete-ticket').hidden=!editing;$('#history').innerHTML=(editing?.history||[]).slice().reverse().map(h=>`<div class="history-row">${esc(h.text)}<small>${esc(new Date(h.at).toLocaleString())}</small></div>`).join('');$('#editor').showModal();}
document.addEventListener('click',e=>{const scope=e.target.closest('[data-scope]'),p=e.target.closest('[data-project]'),v=e.target.closest('[data-view]'),t=e.target.closest('[data-ticket]');if(scope){state.scope=scope.dataset.scope;state.project='';render();}if(p){state.project=p.dataset.project;state.scope='all';render();}if(v){state.view=v.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b===v));render();}if(t)openTicket(Number(t.dataset.ticket));const rm=e.target.closest('[data-remove-check]');if(rm){checks.splice(Number(rm.dataset.removeCheck),1);renderChecks();}});
document.addEventListener('keydown',e=>{const t=e.target.closest('tr[data-ticket]');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openTicket(Number(t.dataset.ticket));}});
$('#new-ticket').onclick=()=>openTicket();$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();
$('#checklist').onchange=e=>{if(e.target.dataset.check!==undefined)checks[Number(e.target.dataset.check)].done=e.target.checked;};
function addCheck(){const el=$('#check-input');if(el.value.trim()){checks.push({text:el.value.trim(),done:false});el.value='';renderChecks();}}
$('#add-check').onclick=addCheck;$('#check-input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addCheck();}};
$('#ticket-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,values=Object.fromEntries(new FormData(f)),at=now(),next=structuredClone(data),t=editing?next.tickets.find(t=>t.id===editing.id):{id:nextId(next),created:at,history:[]};values.title=values.title.trim();if(!values.title){f.elements.title.setCustomValidity('Add a title.');f.elements.title.reportValidity();f.elements.title.setCustomValidity('');return;}if(editing){const changed=['title','project','status','priority','due','description'].filter(k=>values[k]!==editing[k]);if(JSON.stringify(checks)!==JSON.stringify(editing.checks))changed.push('checklist');if(changed.length)t.history.push({at,text:`Updated ${changed.join(', ')}.${values.status!==editing.status?` Status: ${editing.status} → ${values.status}.`:''}`});}else t.history.push({at,text:'Ticket created.'});if(values.note.trim())t.history.push({at,text:values.note.trim()});delete values.note;Object.assign(t,values,{checks:structuredClone(checks),updated:at});if(!editing)next.tickets.push(t);if(persist(next)){$('#editor').close();render();toast('Ticket saved');}};
$('#delete-ticket').onclick=()=>{if(editing&&confirm(`Delete ticket #${editing.id}? This cannot be undone.`)){const next=structuredClone(data);next.tickets=next.tickets.filter(t=>t.id!==editing.id);if(persist(next)){$('#editor').close();render();toast('Ticket deleted');}}};
$('#search').oninput=e=>{state.search=e.target.value;render();};$('#status-filter').onchange=e=>{state.status=e.target.value;render();};$('#priority-filter').onchange=e=>{state.priority=e.target.value;render();};
$('#add-project').onclick=()=>{$('#project-form').reset();$('#project-editor').showModal();};$('#close-project').onclick=()=>$('#project-editor').close();$('#project-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,name=f.elements.name.value.trim();if(!name)return;const next=structuredClone(data),p={id:crypto.randomUUID(),name,color:f.elements.color.value};next.projects.push(p);if(persist(next)){state.project=p.id;state.scope='all';$('#project-editor').close();render();toast('Project created');}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`project-desk-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded');};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup must be smaller than 10 MB.');const next=validateData(JSON.parse(await file.text()));if(confirm(`Replace this browser’s data with ${next.tickets.length} tickets and ${next.projects.length} projects? Download a backup first if you want to keep the current data.`)&&persist(next)){state.project='';state.scope='all';render();toast('Backup restored');}}catch(err){toast('Restore failed: '+err.message);}finally{e.target.value='';}};
render();if(storageIssue){$('#save-state').textContent='Storage needs attention — restore a backup';toast('Saved data could not be read. The stored copy has not been overwritten.');}
